window.openDetails=function(e){$("#details-".concat(e)).slideToggle()},window.openConfig=function(e){Craft.postActionRequest("notifier/log/get-notification",{notificationId:e},(function(e,t){if("success"===t)if(e.success){var o=e.notification;o?Craft.createElementEditor("doublesecretagency\\notifier\\elements\\Notification",{siteId:o.siteId,elementId:o.id,draftId:o.draftId,params:{fresh:1}}):Craft.cp.displayError(Craft.t("notifier","Invalid notification ID."))}else Craft.cp.displayError(e.message||Craft.t("notifier","Something went wrong."));else Craft.cp.displayError(Craft.t("notifier","Unable to get the notification, something went wrong."))}))},window.deleteEnvelope=function(e){confirm(Craft.t("notifier","Are you sure you want to delete this log event?"))&&Craft.postActionRequest("notifier/log/delete",{envelopeId:e},(function(t,o){"success"===o?t.success?($("#envelope-".concat(e)).slideUp(400,(function(){$(".envelope").filter(":visible").length||window.location.reload()})),Craft.cp.displaySuccess(Craft.t("notifier","Log event deleted."))):Craft.cp.displayError(t.message||Craft.t("notifier","Something went wrong.")):Craft.cp.displayError(Craft.t("notifier","Unable to delete the log event, something went wrong."))}))},window.deleteDay=function(e){var t=Craft.t("notifier","Are you sure you want to delete all logs from {date}?",{date:e});confirm(t)&&Craft.postActionRequest("notifier/log/delete-day",{date:e},(function(e,t){"success"===t?window.location.reload():Craft.cp.displayError(Craft.t("notifier","Unable to delete log events, something went wrong."))}))};